function elementosVisibles(items, scrollY, alturaItem, alturaViewport) {
  const inicio = Math.floor(scrollY / alturaItem);
  const fin    = inicio + Math.ceil(alturaViewport / alturaItem);
  return items.slice(inicio, fin);
}
